    divval = None
    for v in {x for row in grid for x in row}:
        if any(all(x == v for x in row) for row in grid) and any(all(row[c] == v for row in grid) for c in range(w)):
            divval = v
            break
    rows = [r for r in range(h) if all(x == divval for x in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == divval for r in range(h))]
    rh = (rows[0] if rows else h)  # vertical period from first panel height
    cw = cols[0] if cols else w
