    # Source is top-left panel; anomalous non-background cells across all panels
    # are projected into every corresponding panel cell position.
    bg = next(v for v in {x for row in grid for x in row} if v != divval and sum(row.count(v) for row in grid) > h*w//2)
    panels_r = [0] + [r+1 for r in rows]
    panels_c = [0] + [c+1 for c in cols]
